def etiket(ad):
    if ad.isupper() and len(ad)>3:
        tr=any(c in ad for c in 'ÇĞÖŞÜİ')
        def low(p): return p.replace('I','ı').replace('İ','i').lower() if tr else p.lower()
        def cap(p): return (p[:1].replace('i','İ').upper()+p[1:]) if p else p
        return ' '.join('&'.join(cap(low(q)) for q in p.split('&')) for p in ad.split(' '))
    return ad
